        }

        h1 {
            font-size: 2rem;
            margin-bottom: 15px;
            color: #4ecdc4;
            text-shadow: 0 2px 4px rgba(0,0,0,0.3);
        }

        .canvas-container {
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
            border-radius: 8px;
            overflow: hidden;
            background-color: #2b3a42;
            margin-bottom: 20px;
