<body>

    <h1>Conway's Game of Life</h1>

    <div class="canvas-container">
        <!-- Grid canvas rendered at >= 400x400 CSS pixels -->
        <canvas id="life" width="600" height="480"></canvas>
    </div>

    <div class="controls">
        <button id="step">Step</button>
        <button id="play">Play</button>
        <button id="random">Random</button>
        <button id="clear">Clear</button>
    </div>

<script>
/**
 * Conway's Game of Life Implementation
 */
(function() {
    'use strict';

    // Configuration: Grid size in cells (must be >= 40x40)
    const W = 60; 
    const H = 40; 

    // Canvas & Context
    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d', { alpha: false });

    // State Buffers (Grid and Next Generation Buffer)
    let grid = [];
    let nextGrid = [];

    // Simulation Control Flag
    let isRunning = false;
    let simulationInterval = null;

    /** Helper to initialize a 2D array of given dimensions */
    function createEmptyGrid(w, h) {
        const row = new Array(h).fill(0); 
        return Array.from({ length: w }, () => [...row]);
    }

    // Initialize Grids (Allocated once for efficiency)
    grid = createEmptyGrid(W, H);
    nextGrid = createEmptyGrid(W, H);

    /** Core API Object exposed on window */
    window.life = {
        get w() { return W; },
        get h() { return H; },

        // Returns 0 or 1. Out of bounds returns 0.
        get(x, y) {
            if (x < 0 || x >= W || y < 0 || y >= H) return 0;
            return grid[x][y];
        },

        // Sets cell state (truthy=alive). Triggers redraw immediately for visual feedback.
        set(x, y, v) {
            if (x >= 0 && x < W && y >= 0 && y < H) {
                grid[x][y] = v ? 1 : 0;
                draw(); 
            }
        },

        // Advances exactly one generation and redraws.
        step() {
            computeNextGeneration();

            // Swap buffers for simultaneous update logic (critical constraint)
            let temp = grid;
            grid = nextGrid;
            nextGrid = temp;

            draw();
        },

        clear() {
            for(let x=0; x<W; x++) {
                for(let y=0; y<H; y++) {
                    grid[x][y] = 0;
                }
            }
            draw();
        }
    };

    /** Simultaneous Update Logic (B3/S23) */
    function computeNextGeneration() {
        for (let x = 0; x < W; x++) {
            for (let y = 0; y < H; y++) {
                let neighbors = 0;

                // Check all 8 surrounding cells
                for (let dx = -1; dx <= 1; dx++) {
                    for (let dy = -1; dy <= 1; dy++) {
                        if (dx === 0 && dy === 0) continue;

                        const nx = x + dx;
                        const ny = y + dy;

                        // Edges are dead: outside bounds returns 0 implicitly by check below.
                        if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
                            neighbors += grid[nx][ny];
                        }
                    }
                }

                const current = grid[x][y] === 1;

                // Rules: 
                // Live cell with 2 or 3 live neighbours survives.
                // Dead cell with exactly 3 live neighbours becomes alive.

                if (current) {
                    nextGrid[x][y] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
                } else {
                    nextGrid[x][y] = (neighbors === 3) ? 1 : 0;
                }
            }
        }
    }

    /** Rendering */
    function draw() {
        // Clear background (dark theme canvas bg is handled by CSS/Canvas fillRect)
        ctx.fillStyle = '#2b3a42'; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Draw live cells (Playful visual: bright color)
        ctx.fillStyle = '#6ee7bd'; 

        const cellW = canvas.width / W;
        const cellH = canvas.height / H;

        for(let x=0; x<W; x++) {
            for(let y=0; y<H; y++) {
                if (grid[x][y]) {
                    // Draw filled rectangle with slight padding to separate cells visually
                    const px = Math.floor(x * cellW);
                    const py = Math.floor(y * cellH);
                    ctx.fillRect(px + 1, py + 1, cellW - 2, cellH - 2);
                }
            }
        }
    }

    /** Play/Pause Control Logic */
    function togglePlay() {
        isRunning = !isRunning;

        const btn = document.getElementById('play');
        if (isRunning) {
            simulationInterval = setInterval(() => window.life.step(), 100); // Speed ms
            btn.textContent = 'Pause'; 
            btn.style.backgroundColor = '#e74c3c'; // Red for stop/pause
        } else {
            clearInterval(simulationInterval);
            btn.textContent = 'Play';
            btn.style.backgroundColor = ''; // Reset to CSS default style (light pink)
        }
    }

    /** Random Seed Logic */
    function randomize() {
        window.life.clear(); 
        for(let x=0; x<W; x++) {
            for(let y=0; y<H; y++) {
                if(Math.random() < 0.3) grid[x][y] = 1; else grid[x][y]=0;
            }
        }
        draw(); // Manual redraw since clear doesn't handle random fill logic directly in API (API just clears). 
    }

    /** Mouse Interaction */
    let isMouseDown = false;

    function getGridPos(e) {
        const rect = canvas.getBoundingClientRect();
        const xRaw = e.clientX - rect.left;
        const yRaw = e.clientY - rect.top;

        // Map pixel to grid coordinate (0-indexed cell index)
        const x = Math.floor(xRaw / (canvas.width / W));
        const y = Math.floor(yRaw / (canvas.height / H));

        return {x, y};
    }

    /** Event Listeners Initialization */

    // Play Button
    document.getElementById('play').addEventListener('click', togglePlay);

    // Step Button
    document.getElementById('step').addEventListener('click', () => window.life.step());

    // Random Button (Optimized direct manipulation for performance)
    document.getElementById('random').addEventListener('click', randomize);

    // Clear Button
    document.getElementById('clear').addEventListener('click', () => window.life.clear());

    // Canvas Interaction: Clicking / Dragging toggles cells.
    canvas.addEventListener('mousedown', (e) => {
        isMouseDown = true;
        const pos = getGridPos(e);
        if(pos.x >=0 && pos.x < W && pos.y >= 0 && pos.y < H) {
            // TOGGLE Logic: Flip state directly in buffer to reflect immediately
            grid[pos.x][pos.y] = (grid[pos.x][pos.y] === 1 ? 0 : 1);
            draw(); 
        }
    });

    canvas.addEventListener('mousemove', (e) => {
        if(isMouseDown) {
            const pos = getGridPos(e);
            // Only act if inside bounds to prevent error or out of grid behavior?
            if(pos.x >=0 && pos.x < W && pos.y >= 0 && pos.y < H) {
                // TOGGLE Logic for dragging: Flip state again at new cell location.
                 grid[pos.x][pos.y] = (grid[pos.x][pos.y] === 1 ? 0 : 1);
                 draw(); 
            }
        }
    });

    window.addEventListener('mouseup', () => {
        isMouseDown = false;
    });

    // Initialize Display on Load (Draw initial empty grid)
    draw();

})();
</script>
</body>
</html>
